body:
‼️

That's a nice find. While reviewing your latest change I found a problem with WebKit setting form to null eagerly on removal before calling reset form owner.

<details><summary>WPT</summary>

```
  <!doctype html>
  <meta charset="utf-8">
  <title>Disconnecting a form-attribute control whose owner doesn't change</title>
  <script src="/resources/testharness.js"></script>
  <script src="/resources/testharnessreport.js"></script>
  <body>
  <script>
  customElements.define("x-control", class extends HTMLElement {
    static formAssociated = true;
    log = [];
    formAssociatedCallback(form) { this.log.push(form); }
  });

  test(t => {
    const container = document.body.appendChild(document.createElement("div"));
    t.add_cleanup(() => container.remove());
    container.innerHTML = '<form id="f"><x-control form="f"></x-control></form>';
    const control = container.querySelector("x-control");
    control.log = [];

    container.remove();

    assert_array_equals(control.log, [], "the owner never changes, so no callback");
  }, "Disconnecting doesn't call formAssociatedCallback when the owner stays the same");

  test(t => {
    const container = document.body.appendChild(document.createElement("div"));
    t.add_cleanup(() => container.remove());
    container.innerHTML = '<form id="f"><input type="radio" name="g" form="f"></form>' +
                          '<input type="radio" name="g">';
    const [associated, ownerless] = container.querySelectorAll("input");
    associated.checked = true;
    ownerless.checked = true;

    container.remove();

    assert_true(ownerless.checked, "the associated radio never joins the ownerless group");
  }, "Disconnecting doesn't pass a radio through the ownerless group when the owner stays the same");
  </script>
```
</details>

I have a case here where all 3 browsers behave differently. I guess this one is mostly related to the callbacks which we'll deal with as follow-ups but it's the same underlying cause in WebKit I believe.

Chrome:
```
owner before removal: outside (expected outside)
callbacks: ancestor (expected ancestor)
owner after removal: ancestor (expected ancestor)
PASS
```

Firefox: 
```
owner before removal: outside (expected outside)
callbacks: null (expected ancestor)
owner after removal: null (expected ancestor)
FAIL
```

WebKit:
```
owner before removal: outside (expected outside)
callbacks: null, ancestor, null, ancestor (expected ancestor)
owner after removal: ancestor (expected ancestor)
FAIL
```

<details>
<summary>Example</summary>
```html
<!DOCTYPE html>
<meta charset="utf-8">
<title>formAssociatedCallback when a form-attribute control is disconnected</title>
<body>
<pre id="log"></pre>
<script>
const log = message => document.getElementById("log").textContent += message + "\n";
const describe = form => form ? form.id : "null";

customElements.define("x-control", class extends HTMLElement {
  static formAssociated = true;
  calls = [];
  internals = this.attachInternals();
  formAssociatedCallback(form) { this.calls.push(form); }
});

const outside = document.body.appendChild(document.createElement("form"));
outside.id = "outside";
const container = document.body.appendChild(document.createElement("div"));
container.innerHTML = '<form id="ancestor"><x-control form="outside"></x-control></form>';
const ancestor = container.querySelector("form");
const control = container.querySelector("x-control");

log("owner before removal: " + describe(control.internals.form) + " (expected outside)");
control.calls = [];

container.remove();

const calls = control.calls.map(describe).join(", ") || "(none)";
log("callbacks: " + calls + " (expected ancestor)");
log("owner after removal: " + describe(control.internals.form) + " (expected ancestor)");
log(calls === "ancestor" && control.internals.form === ancestor ? "PASS" : "FAIL");
</script>
</body>
```
</details>
